  const GLOSS = [
    { en: 'ERP (enterprise resource planning)', es: 'ERP (sistema de planeación de recursos)',
      def: 'El sistema central de la empresa para compras, inventario y finanzas. Aquí, su motor de reabasto calcula cada noche el pedido de cada tienda con el pronóstico publicado.',
      say: 'The ERP reads the forecast view at four a.m. and computes every store order.' },
    { en: 'distribution center (DC)', es: 'centro de distribución (CD)',
      def: 'Almacén regional que recibe la mercancía de los proveedores y surte a las tiendas. Planea sus compras con horizontes más largos que las tiendas.',
      say: 'Each distribution center delivers store orders the next day.' },
    { en: 'SKU (stock keeping unit)', es: 'SKU (producto, unidad de inventario)',
      def: 'Cada producto distinto que se inventaría (marca, tamaño, presentación). Una serie de este caso es un par tienda × SKU.',
      say: 'Each store carries about twelve thousand SKUs.' },
    { en: 'point of sale (POS)', es: 'punto de venta (POS)',
      def: 'El sistema de cajas de la tienda. Registra ventas, no demanda: un producto agotado no aparece en el POS aunque alguien lo haya buscado.',
      say: 'POS data lands in the warehouse by half past midnight.' },
    { en: 'out-of-stock (OOS)', es: 'agotado',
      def: 'Producto sin existencia en el anaquel. Su tasa (en revisiones de anaquel o con la marca de existencia cero al cierre) es una métrica de negocio y la causa de la demanda censurada.',
      say: 'Out-of-stock days are excluded from training targets.' },
    { en: 'censored demand', es: 'demanda censurada',
      def: 'Demanda que no se observa completa porque la venta quedó limitada por la existencia: el día agotado, la venta es una cota inferior. Tratarla como demanda hace que el modelo pida cada vez menos.',
      say: 'Sales on a stockout day are censored demand, not low demand.' },
    { en: 'phantom inventory', es: 'inventario fantasma',
      def: 'Existencia que el sistema registra pero no está en el anaquel (merma no registrada, robo, errores de conteo). No genera marca de agotado y el ERP no pide.',
      say: 'Long runs of zero sales with positive stock usually mean phantom inventory.' },
    { en: 'shrink', es: 'merma',
      def: 'Pérdida de inventario: mercancía que se tira (caducada, dañada), se roba o desaparece por errores. En frescos, la merma por caducidad es la parte grande y la que el pronóstico puede bajar.',
      say: 'Fresh shrink is about four percent of fresh sales.' },
    { en: 'safety stock', es: 'inventario de seguridad',
      def: 'Colchón por encima de la demanda esperada para cubrir la incertidumbre del pronóstico durante el periodo que cubre un pedido. Aquí sale de la diferencia entre el P90 y el P50.',
      say: 'Safety stock comes from the gap between the ninetieth percentile and the median.' },
    { en: 'lead time', es: 'tiempo de entrega (de reposición)',
      def: 'Tiempo entre que se hace un pedido y la mercancía llega a la tienda. Con 1 día de entrega y revisión diaria, cada pedido cubre 2 días de demanda.',
      say: 'With a one-day lead time and daily reviews, each order covers two days.' },
    { en: 'review period', es: 'periodo de revisión',
      def: 'Cada cuánto se vuelve a pedir. Sumado al tiempo de entrega, define cuántos días de demanda tiene que cubrir un pedido.',
      say: 'The review period is one day because stores order every night.' },
    { en: 'order-up-to level', es: 'nivel objetivo (pedir hasta)',
      def: 'La cantidad hasta la que se repone el inventario disponible (existencia + en camino) en cada pedido. Aquí, la suma de los P90 de los días que cubre el pedido.',
      say: 'The order-up-to level is the sum of the ninetieth percentiles for the next two days.' },
    { en: 'case pack', es: 'empaque (caja de reposición)',
      def: 'Unidades por caja en que se surte un producto. El ERP redondea cada pedido a múltiplos del empaque; el pronóstico va en piezas y no sabe de cajas.',
      say: 'The ERP rounds each order to the case pack; the forecast stays in units.' },
    { en: 'forecast horizon', es: 'horizonte de pronóstico',
      def: 'Cuántos periodos hacia adelante se pronostica (aquí, 14 días) y, por fila, cuántos días hay entre el último día cerrado (run_date) y la fecha objetivo (h = 1 a 14).',
      say: 'We forecast fourteen days ahead, and the error grows with the horizon.' },
    { en: 'quantile forecast', es: 'pronóstico por cuantiles',
      def: 'Pronóstico que da valores de la distribución de la demanda, no solo uno: el P50 (mediana) y el P90 (90 % de los días la venta queda por debajo).',
      say: 'We publish quantile forecasts, a median and a ninetieth percentile.' },
    { en: 'pinball loss', es: 'pérdida pinball (cuantílica)',
      def: 'Pérdida para entrenar y evaluar un cuantil τ: τ × (A − Q) si la venta A queda arriba de Q, y (1 − τ) × (Q − A) si queda abajo. Con τ = 0.9, quedarse corto pesa nueve veces más que pasarse.',
      say: 'Each quantile model minimizes the pinball loss for its own alpha.' },
    { en: 'WAPE (weighted absolute percentage error)', es: 'error porcentual absoluto ponderado',
      def: 'Suma de errores absolutos dividida entre la suma de lo vendido. A diferencia del MAPE, no se indefine con ventas en cero; pesa por volumen, así que se reporta por segmento.',
      say: 'Top-series WAPE is about forty-five percent today, and the target is thirty-five.' },
    { en: 'forecast bias', es: 'sesgo del pronóstico',
      def: '(Σ pronóstico − Σ venta) ÷ Σ venta: positivo, se pronostica de más (merma); negativo, de menos (agotados). Con un P50 de series sesgadas sale negativo aunque el modelo sea bueno.',
      say: 'A positive bias on fresh items turns directly into waste.' },
    { en: 'quantile coverage', es: 'cobertura del cuantil',
      def: 'Fracción de días en que la venta real quedó por debajo de un cuantil. Un P90 bien calibrado cubre ≈ 90 % de los días sin agotado.',
      say: 'We check that the ninetieth percentile covers about ninety percent of non-stockout days.' },
    { en: 'seasonal naive forecast', es: 'pronóstico ingenuo estacional',
      def: 'Pronosticar el valor del mismo periodo de la estación anterior; aquí, la venta del mismo día de la semana pasada. Es la referencia que un modelo tiene que superar y el último escalón del fallback.',
      say: 'The seasonal naive forecast is today’s spreadsheet, and the model has to beat it per segment.' },
    { en: 'rolling-origin backtest', es: 'backtest con origen móvil',
      def: 'Evaluación que repite “entrenar con datos hasta un origen y pronosticar los días siguientes” para varios orígenes (aquí, 8 domingos), y promedia. Mide la receta sin mirar el futuro.',
      say: 'Any recipe change has to win a rolling-origin backtest over eight weekly origins.' },
    { en: 'global forecasting model', es: 'modelo global de pronóstico',
      def: 'Un solo modelo entrenado sobre muchas series a la vez, con atributos de la serie como features, en lugar de un modelo por serie. Las series escasas y las nuevas aprenden de las parecidas.',
      say: 'One global model learns from millions of series at once.' },
    { en: 'direct multi-horizon forecasting', es: 'pronóstico directo multi-horizonte',
      def: 'Predecir cada horizonte desde los datos reales al origen, con el horizonte como feature, en vez de encadenar pronósticos día por día (recursivo), que propaga los errores.',
      say: 'We forecast all fourteen horizons directly, so errors don’t compound.' },
    { en: 'quantile crossing', es: 'cruce de cuantiles',
      def: 'Cuando dos modelos de cuantiles entrenados por separado dan un P90 menor que el P50 en alguna fila. Se corrige ordenando los dos valores por fila (rearrangement) y se cuenta.',
      say: 'We fix quantile crossing after prediction and alert if it stops being rare.' },
    { en: 'intermittent demand', es: 'demanda intermitente',
      def: 'Series con muchos días sin venta y ventas esporádicas. Su mediana diaria suele ser cero; los métodos clásicos para ellas son Croston y su variante TSB.',
      say: 'Most of the long tail is intermittent demand, so its orders are driven by the high quantile.' },
    { en: 'Croston’s method', es: 'método de Croston',
      def: 'Método clásico para demanda intermitente (Croston, 1972): estima por separado el tamaño de la demanda y el intervalo entre ventas. TSB (Teunter, Syntetos y Babai, 2011) lo corrige para productos que dejan de venderse.',
      say: 'Croston or TSB is the classical baseline for intermittent series.' },
    { en: 'known-future covariate', es: 'variable conocida a futuro',
      def: 'Feature que se conoce por adelantado para las fechas objetivo: calendario, feriados, promociones y precios planeados. Se usa con la versión vigente en el origen.',
      say: 'Planned promotions are known-future covariates, unlike next week’s sales.' },
    { en: 'payday effect', es: 'efecto quincena',
      def: 'El aumento de compras en los días posteriores al pago de salario; en México, las quincenas del 15 y del último día del mes, movidas al día hábil anterior cuando caen en fin de semana según cada empleador.',
      say: 'The payday effect shows up twice a month in Mexico.' },
    { en: 'analog forecasting', es: 'pronóstico por análogos',
      def: 'Pronosticar un producto o tienda sin historia con la curva de productos o tiendas parecidos (misma categoría, marca y rango de precio; mismo formato y región).',
      say: 'New products start with analog forecasts from similar items.' },
    { en: 'hierarchical reconciliation', es: 'reconciliación jerárquica',
      def: 'Ajustar pronósticos de distintos niveles (tienda, categoría, CD, cadena) para que sean coherentes entre sí: bottom-up, top-down u óptima (MinT).',
      say: 'Store-level forecasts don’t add up to the category plan without reconciliation.' },
    { en: 'forecast value added (FVA)', es: 'valor agregado del pronóstico',
      def: 'Cuánto mejora (o empeora) el error cada paso del proceso respecto del anterior: el modelo contra el seasonal naive, y los ajustes humanos contra el modelo.',
      say: 'Forecast value added shows where manager overrides help and where they hurt.' },
    { en: 'difference-in-differences (DiD)', es: 'diferencia en diferencias',
      def: 'Efecto estimado como el cambio del grupo tratado menos el cambio del grupo de control en el mismo periodo, para descontar la temporada y otros cambios comunes.',
      say: 'The store pilot is read with difference-in-differences against matched controls.' },
    { en: 'DAG (directed acyclic graph)', es: 'DAG (grafo dirigido acíclico)',
      def: 'La definición de un workflow como tareas con dependencias y sin ciclos; en Airflow, cada DAG se ejecuta por fecha.',
      say: 'The forecast_nightly DAG runs every night with one partition per date.' },
    { en: 'Airflow sensor', es: 'sensor (Airflow)',
      def: 'Tarea que espera una condición (un archivo, una partición completa, una hora) antes de dejar seguir al DAG. En modo reschedule o deferrable no ocupa un worker mientras espera.',
      say: 'Sensors wait for each store’s data until the one thirty cutoff.' },
    { en: 'Deadline Alerts (Airflow)', es: 'alertas de fecha límite (Airflow)',
      def: 'Mecanismo de Airflow 3.1+ que reemplaza a los SLAs que se quitaron en 3.0: un punto de referencia, un intervalo y un callback por DAG. Avisa; no publica ni corrige nada.',
      say: 'A deadline alert tells us the run is late, but the fallback doesn’t depend on it.' },
    // Chips: definidos antes en otras páginas (gana su definición); se repiten con la misma grafía.
    { en: 'Apache Airflow', es: 'Airflow', def: 'Orquestador de workflows en Python.',
      say: 'Airflow orchestrates the nightly run; Spark does the heavy lifting.' },
    { en: 'Apache Spark', es: 'Spark', def: 'Motor de procesamiento distribuido.',
      say: 'Spark builds features per store, one shard per store.' },
    { en: 'GBDT (gradient-boosted decision trees)', es: 'árboles con gradient boosting', def: 'Ensamble de árboles entrenados en secuencia.',
      say: 'Two gradient-boosted quantile models score sixty-seven million rows in minutes on CPU.' },
    { en: 'atomic swap', es: 'swap atómico', def: 'Cambiar un puntero de una sola vez.',
      say: 'Publishing is an atomic swap of the forecast view.' },
    { en: 'write-audit-publish (WAP)', es: 'escribir, auditar, publicar', def: 'Patrón de publicación con validación intermedia.',
      say: 'We write a new partition, audit it with the gate, then publish.' },
    { en: 'temporal split', es: 'split temporal', def: 'Partir por tiempo.',
      say: 'Every evaluation is a temporal split from a forecast origin.' },
    { en: 'feedback loop', es: 'ciclo de retroalimentación', def: 'Las predicciones influyen en los datos futuros.',
      say: 'Treating stockouts as low demand creates a feedback loop of smaller orders.' },
    { en: 'backfill', es: 'reproceso histórico', def: 'Recalcular datos de fechas pasadas.',
      say: 'Backfills write their partition but never publish.' },
    { en: 'cold-start problem', es: 'problema de arranque en frío', def: 'Entidades nuevas sin historia.',
      say: 'New stores and products are a cold-start problem handled with analogs and clusters.' },
    { en: 'spot instance', es: 'instancia spot', def: 'Capacidad interrumpible con descuento.',
      say: 'Feature builds run on spot, with the last retry on on-demand.' },
    { en: 'point-in-time correctness', es: 'corrección point-in-time', def: 'Cada fila usa los valores vigentes en su instante.',
      say: 'With fourteen horizons, point-in-time correctness means features as of the forecast origin.' },
    { en: 'long tail', es: 'cola larga', def: 'Muchos ítems con poca frecuencia.',
      say: 'Sixty percent of the series are a long tail selling under one unit a day.' },
  ];

